<?php
$rows=ak_rows('SELECT * FROM ak_jam_belajar ORDER BY id');
?><section class="panel"><h2>Hari dan waktu belajar</h2><p>Referensi dari gambar yang diberikan pengguna. Upacara, kegiatan Jumat, istirahat, dan jeda dibedakan dari jam pelajaran. Referensi ini tidak mengubah penugasan atau pertemuan yang sudah disimpan.</p></section>
<?php foreach($rows as $row):$profile=json_decode($row['payload_json'],true,512,JSON_THROW_ON_ERROR);?><section class="panel"><h2><?=e($row['nama'])?> · versi <?=e($row['versi'])?></h2><p class="muted"><?=e($row['catatan'])?></p><?php if($row['status']==='perlu_konfirmasi'):?><div class="notice">Masih perlu konfirmasi pembacaan waktu Jumat. Rentang dipertahankan sesuai gambar, bukan diseragamkan otomatis.</div><?php endif;?><div class="table-scroll"><table class="bell-reference"><thead><tr><th>Jam ke</th><th>Waktu</th><th>Keterangan</th></tr></thead><tbody><?php foreach($profile['slots'] as [$number,$from,$until,$label]):?><tr><td><?=e($number??'—')?></td><td><?=e($from)?>–<?=e($until)?></td><td class="wrap"><?=e($label)?></td></tr><?php endforeach;?></tbody></table></div></section><?php endforeach;?>
